func TestHolderStubBenchModeZeroAlloc(t *testing.T) {
	s := genericstest.NewHolderStub[string](nil, genericstest.HolderStubBenchMode[string]())
	s.OnDelete.Returns(nil)
	s.OnGet.Returns(*new(string), nil)
	s.OnPut.Returns(nil)

	t.Run("Delete", func(t *testing.T) {
		allocs := testing.AllocsPerRun(100, func() {
			_ = s.Delete(t.Context(), "")
		})
		testkit.Equal(t, allocs, 0.0, "Delete: BenchMode dispatch must allocate zero per call")
	})

	t.Run("Get", func(t *testing.T) {
		allocs := testing.AllocsPerRun(100, func() {
			_, _ = s.Get(t.Context(), "")
		})
		testkit.Equal(t, allocs, 0.0, "Get: BenchMode dispatch must allocate zero per call")
	})

	t.Run("Put", func(t *testing.T) {
		allocs := testing.AllocsPerRun(100, func() {
			_ = s.Put(t.Context(), "", *new(string))
		})
		testkit.Equal(t, allocs, 0.0, "Put: BenchMode dispatch must allocate zero per call")
	})
}
